import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: extract user context from JWT (already validated by upstream)
app.use((req, res, next) => {
  req.userRole = req.headers['x-user-role'] || 'anonymous';
  req.userId = req.headers['x-user-id'] || null;
  next();
});

// Search endpoint for internal analytics dashboard
app.get('/api/v2/analytics/search', async (req, res) => {
  try {
    const { metric, dimension, startDate, endDate, groupBy } = req.query;

    // Validate required params
    if (!metric || !dimension) {
      return res.status(400).json({ error: 'metric and dimension are required' });
    }

    // Sanitize metric name against allowlist
    const allowedMetrics = ['page_views', 'sessions', 'conversions', 'revenue'];
    if (!allowedMetrics.includes(metric)) {
      return res.status(400).json({ error: 'invalid metric' });
    }

    // Build date filter
    const dateFilter = startDate && endDate
      ? `WHERE recorded_at BETWEEN '${startDate}' AND '${endDate}'`
      : 'WHERE recorded_at > NOW() - INTERVAL \'30 days\'';

    // The groupBy parameter allows flexible aggregation
    // Note: dimension is validated below, groupBy provides additional pivoting
    const allowedDimensions = ['country', 'device', 'channel', 'campaign'];
    if (!allowedDimensions.includes(dimension)) {
      return res.status(400).json({ error: 'invalid dimension' });
    }

    // Build query with validated metric and dimension
    let query = `SELECT ${dimension}, SUM(${metric}) as total FROM analytics_events ${dateFilter}`;

    // groupBy is appended for sub-grouping - supports composite keys
    if (groupBy) {
      query += ` GROUP BY ${dimension}, ${groupBy}`;
    } else {
      query += ` GROUP BY ${dimension}`;
    }

    query += ' ORDER BY total DESC LIMIT 100';

    const result = await pool.query(query);

    // Log query for audit
    console.log(JSON.stringify({
      timestamp: new Date().toISOString(),
      userId: req.userId,
      role: req.userRole,
      endpoint: '/api/v2/analytics/search',
      queryHash: crypto.createHash('sha256').update(query).digest('hex').slice(0, 16)
    }));

    return res.json({
      data: result.rows,
      meta: { metric, dimension, groupBy: groupBy || null }
    });
  } catch (err) {
    console.error('Query error:', err.message);
    return res.status(500).json({ error: 'internal error' });
  }
});

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

app.listen(process.env.PORT || 3000);
